import numpy as np
R=np.load('R.npy'); T=len(R)
sr=lambda x: x.mean()/x.std()*np.sqrt(252)
def methods(A):
    m=A.mean(0); sd=A.std(0); s=m/sd; out={}
    for k in [10,30,60,100,423]:
        o=np.argsort(-np.abs(s))[:k]; w=np.zeros(A.shape[1]); w[o]=np.sign(s[o])/sd[o]; out[f'top{k}']=w
    C=np.cov(A.T)
    for lam in [0.5,0.9,0.99]:
        Cs=(1-lam)*C+lam*np.diag(np.diag(C)); out[f'mv{lam}']=np.linalg.solve(Cs,m)
    return out
# rolling: fit on fold, test on next
cuts=np.linspace(0,T,6).astype(int)
res={}
for i in range(1,5):
    A=R[:cuts[i]]; B=R[cuts[i]:cuts[i+1]]
    for k,w in methods(A).items(): res.setdefault(k,[]).append(sr(B@w))
for k,v in res.items(): print(k, np.round(v,2), np.mean(v).round(2))
